#define MAX_EXPANDO_SIGNALS 10

typedef struct {
        EXPANDO_FUNC func;

        int signals;
        int signal_ids[MAX_EXPANDO_SIGNALS];
        int signal_args[MAX_EXPANDO_SIGNALS];
} EXPANDO_REC;

